<script setup>
import {computed,ref} from 'vue';import {resolveThreadMaterial} from '../../core/thread-estimate-workflow.mjs';import {inventorySummary} from '../../core/inventory.mjs';import AppDialog from './AppDialog.vue';import FormField from './FormField.vue';import {state,normalize} from '../state';import {t,number,errorText} from '../i18n';import {threadSubstitutionOptions,substitutedThreadColor} from '../thread-substitutions.mjs';
const props=defineProps({color:{type:Object,required:true},apply:{type:Function,required:true}}),emit=defineEmits(['close']);const query=ref(''),selected=ref(''),confirmed=ref(false),error=ref('');const rows=computed(()=>threadSubstitutionOptions(state.value,props.color)),matches=computed(()=>rows.value.filter(row=>normalize([row.material.name,row.material.brand,row.material.range,row.material.code].join(' ')).includes(normalize(query.value)))),visible=computed(()=>matches.value.slice(0,40)),choice=computed(()=>rows.value.find(row=>row.material.id===selected.value));
const source=computed(()=>{try{const material=resolveThreadMaterial(state.value,props.color);return material?{material,...inventorySummary(state.value,material.id)}:null;}catch{return null;}});
function save(){try{const color=substitutedThreadColor(props.color,choice.value?.material,confirmed.value);if(props.apply(color)===false)throw Object.assign(new Error(),{code:'thread_substitution_apply'});emit('close');}catch(caught){error.value=errorText(caught);}}
</script>
<template><AppDialog :title="t('threadSubstitutions')" wide @close="emit('close')"><p class="notice">{{t('threadSubstitutionHelp')}}</p><p><span class="swatch" :style="{background:color.hex}"/> {{color.brand}} {{color.range}} {{color.code}} · {{color.name}} · {{color.strands}} {{t('strands')}}</p><p v-if="source" class="field-help">{{t('available')}}: {{source.estimated?'≈ ':''}}{{number(source.available,6)}} {{t(`unit_${source.material.unit}`)}} {{source.unknown?` + ${t('unknown')}`:''}} · {{t('reserved')}}: {{number(source.reserved,6)}} {{t(`unit_${source.material.unit}`)}}</p><p v-else class="field-help">{{t('threadSourceUnbound')}}</p><p v-if="error" class="notice error" role="alert">{{error}}</p><FormField :label="t('threadSearchColors')" v-slot="{id}"><input :id="id" v-model="query" type="search"/></FormField><p class="field-help">{{t('threadSubstitutionLimit')}} · {{matches.length}}</p><div class="table-wrap"><table><thead><tr><th>{{t('materials')}}</th><th>ΔE76 ≈</th><th>{{t('available')}}</th><th/></tr></thead><tbody><tr v-for="row in visible" :key="row.material.id"><td><span class="swatch" :style="{background:row.material.color}"/>{{row.material.brand}} {{row.material.range}} {{row.material.code}}<span class="cell-subtitle">{{row.material.name}} · {{row.sameIdentity?t('threadSameIdentity'):t('threadDifferentIdentity')}}</span></td><td>{{number(row.distance,2)}}</td><td>{{row.estimated?'≈ ':''}}{{number(row.available,6)}} {{t(`unit_${row.material.unit}`)}}<span v-if="row.unknown" class="cell-subtitle">+ {{t('unknown')}}</span><span class="cell-subtitle">{{t('reserved')}}: {{number(row.reserved,6)}} {{t(`unit_${row.material.unit}`)}}</span><span class="cell-subtitle">{{t('threadSubstitutionMetres')}}: <span>{{row.filamentMetres===null?t('threadSubstitutionConversionUnknown'):number(row.filamentMetres,6)}}</span></span></td><td><button class="button small" :aria-pressed="selected===row.material.id" @click="selected=row.material.id;confirmed=false">{{t('threadChooseSubstitute')}}</button></td></tr></tbody></table></div><p v-if="!matches.length" class="field-help">{{t('noResults')}}</p><template v-if="choice"><p class="notice">{{t('threadChosenSubstitute')}}: {{choice.material.brand}} {{choice.material.range}} {{choice.material.code}} · {{choice.material.name}} · ΔE76 ≈ {{number(choice.distance,2)}}</p><label class="checkbox-label"><input v-model="confirmed" type="checkbox"/>{{t('threadSubstitutionConfirm')}}</label></template><template #footer><button class="button" @click="emit('close')">{{t('cancel')}}</button><button class="button primary" :disabled="!choice||!confirmed" @click="save">{{t('threadSubstitutionApply')}}</button></template></AppDialog></template>
